// flash the onboard led as an out-of-band diagnostic tool
static void checkpoint(unsigned n) {
    for (unsigned i = 0; i < n; ++i) {
        digitalWrite(LED_PIN, HIGH);
        delay(80);
        digitalWrite(LED_PIN, LOW);
        delay(80);
    }
    delay(400);
}

