static void qsDrainTask(void* arg) {
    (void)arg;

    vTaskDelay(pdMS_TO_TICKS(1000));

    for (;;) {
        uint16_t n = 256U;
        uint8_t const* block;

        QS_CRIT_STAT_
        QS_CRIT_E_();
        block = QP::QS::getBlock(&n);
        QS_CRIT_X_();

        if ((block != nullptr) && (n != 0U)) {
            qsSerial.write(block, n);
        }

        vTaskDelay(pdMS_TO_TICKS(2));
    }
}

